package io.github.diodeme.ji.security.secret;

import java.nio.file.Path;
import java.util.Objects;

/** Separate source contract for Host identity material; it cannot be used as a master-key resolver. */
public interface HostIdentityKeySource {
    HostIdentityKey load();

    record HostIdentityKey(Path privateKeyFile, String publicKeyFingerprint) {
        public HostIdentityKey {
            Objects.requireNonNull(privateKeyFile, "privateKeyFile");
            if (publicKeyFingerprint == null || publicKeyFingerprint.isBlank()) {
                throw new IllegalArgumentException("publicKeyFingerprint must not be blank");
            }
        }

        @Override
        public String toString() {
            return "HostIdentityKey[privateKeyFile=REDACTED, publicKeyFingerprint=" + publicKeyFingerprint + "]";
        }
    }
}
